CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Tehran', automation_enabled boolean NOT NULL DEFAULT true, retention_days int NOT NULL DEFAULT 365 CHECK(retention_days >= 30));
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, email text NOT NULL, display_name text NOT NULL, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('SUPER_ADMIN','ORG_ADMIN','SUPERVISOR','AGENT','ANALYST','INTEGRATION_MANAGER','AUDITOR')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,email), UNIQUE(id,organization_id));
CREATE UNIQUE INDEX users_email_login ON users(lower(email));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_definitions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id));
CREATE TABLE agent_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agent_id uuid NOT NULL REFERENCES agent_definitions, version int NOT NULL, prompt text NOT NULL, provider text NOT NULL CHECK(provider IN ('openai','local')), model text NOT NULL, max_output_tokens int NOT NULL CHECK(max_output_tokens BETWEEN 32 AND 4096), debounce_seconds int NOT NULL DEFAULT 4 CHECK(debounce_seconds BETWEEN 0 AND 30), input_price_per_million numeric(18,6), output_price_per_million numeric(18,6), currency text NOT NULL DEFAULT 'USD', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(agent_id,version));
CREATE TABLE wa_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, display_phone text, timezone text NOT NULL DEFAULT 'Asia/Tehran', status text NOT NULL DEFAULT 'CREATED', enabled boolean NOT NULL DEFAULT false, ai_enabled boolean NOT NULL DEFAULT false, allow_cloud boolean NOT NULL DEFAULT false, agent_id uuid, version int NOT NULL DEFAULT 1, qr text, qr_expires_at timestamptz, last_error text, last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id), FOREIGN KEY(agent_id,organization_id) REFERENCES agent_definitions(id,organization_id));
CREATE TABLE user_account_access (user_id uuid NOT NULL, account_id uuid NOT NULL, organization_id uuid NOT NULL, PRIMARY KEY(user_id,account_id), FOREIGN KEY(user_id,organization_id) REFERENCES users(id,organization_id) ON DELETE CASCADE, FOREIGN KEY(account_id,organization_id) REFERENCES wa_accounts(id,organization_id) ON DELETE CASCADE);
CREATE TABLE wa_session_leases (account_id uuid PRIMARY KEY REFERENCES wa_accounts, worker_id text NOT NULL, fencing_token bigint NOT NULL DEFAULT 1, lease_until timestamptz NOT NULL);
CREATE TABLE wa_auth_credentials (account_id uuid PRIMARY KEY REFERENCES wa_accounts, ciphertext text NOT NULL, key_version int NOT NULL DEFAULT 1, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wa_auth_signal_keys (account_id uuid NOT NULL REFERENCES wa_accounts, category text NOT NULL, key_id text NOT NULL, ciphertext text NOT NULL, key_version int NOT NULL DEFAULT 1, PRIMARY KEY(account_id,category,key_id));
CREATE TABLE contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, display_name text NOT NULL, opted_out boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contact_identifiers (account_id uuid NOT NULL REFERENCES wa_accounts, jid text NOT NULL, contact_id uuid NOT NULL REFERENCES contacts, kind text NOT NULL, PRIMARY KEY(account_id,jid));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES wa_accounts, contact_id uuid NOT NULL REFERENCES contacts, remote_jid text NOT NULL, mode text NOT NULL DEFAULT 'AI' CHECK(mode IN ('AI','HUMAN','ASSIST','PAUSED')), status text NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','CLOSED')), version int NOT NULL DEFAULT 1, assigned_to uuid REFERENCES users, tags text[] NOT NULL DEFAULT '{}', unread_count int NOT NULL DEFAULT 0, last_message_at timestamptz NOT NULL DEFAULT now(), opened_at timestamptz NOT NULL DEFAULT now(), closed_at timestamptz, resolved_by text, last_preview text NOT NULL DEFAULT '', UNIQUE(account_id,remote_jid));
CREATE INDEX conversations_inbox ON conversations(account_id,last_message_at DESC,id DESC);
CREATE TABLE inbox_receipts (account_id uuid NOT NULL REFERENCES wa_accounts, dedupe_key text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(account_id,dedupe_key));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES wa_accounts, conversation_id uuid NOT NULL REFERENCES conversations, dedupe_key text NOT NULL, external_id text, direction text NOT NULL CHECK(direction IN ('INBOUND','OUTBOUND')), source text NOT NULL CHECK(source IN ('CUSTOMER','HUMAN','AI','DEVICE')), body text NOT NULL, history boolean NOT NULL DEFAULT false, event_time timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL DEFAULT 'RECEIVED', raw_ciphertext text, UNIQUE(account_id,dedupe_key));
CREATE INDEX messages_timeline ON messages(conversation_id,event_time DESC,id DESC);
CREATE INDEX messages_external ON messages(account_id,external_id);
CREATE TABLE message_status_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), message_id uuid NOT NULL REFERENCES messages, status text NOT NULL, recorded_at timestamptz NOT NULL DEFAULT now(), UNIQUE(message_id,status));
CREATE TABLE conversation_activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations, actor_id uuid REFERENCES users, kind text NOT NULL, body text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES wa_accounts, conversation_id uuid NOT NULL REFERENCES conversations, conversation_version int NOT NULL, agent_version_id uuid REFERENCES agent_versions, provider text NOT NULL, model text NOT NULL, status text NOT NULL CHECK(status IN ('RUNNING','SUCCEEDED','DRAFT','STALE','FAILED')), input_tokens int, output_tokens int, cost_minor numeric(18,6), currency text NOT NULL DEFAULT 'USD', latency_ms int, reply text, error_code text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz, UNIQUE(conversation_id,conversation_version));
CREATE UNIQUE INDEX one_live_run ON agent_runs(conversation_id) WHERE status='RUNNING';
CREATE TABLE outbound_intents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES wa_accounts, conversation_id uuid NOT NULL REFERENCES conversations, run_id uuid UNIQUE REFERENCES agent_runs, operation_id text NOT NULL, expected_version int NOT NULL, source text NOT NULL CHECK(source IN ('HUMAN','AI')), body text NOT NULL, status text NOT NULL DEFAULT 'QUEUED' CHECK(status IN ('QUEUED','SENDING','ACCEPTED','DELIVERED','READ','UNKNOWN_DELIVERY','FINAL_FAILURE','CANCELLED')), external_id text, error_code text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(account_id,operation_id));
CREATE INDEX outbound_pending ON outbound_intents(account_id,created_at) WHERE status='QUEUED';
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, account_id uuid REFERENCES wa_accounts, event_type text NOT NULL, event_version int NOT NULL DEFAULT 1, aggregate_id uuid NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE INDEX outbox_pending ON outbox_events(occurred_at) WHERE published_at IS NULL;
CREATE TABLE consumer_inbox (consumer_name text NOT NULL, event_id uuid NOT NULL REFERENCES outbox_events, consumed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_name,event_id));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, actor_id uuid REFERENCES users, action text NOT NULL, target text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_time ON audit_logs(organization_id,occurred_at DESC);
CREATE TABLE fact_messages (message_id uuid PRIMARY KEY REFERENCES messages ON DELETE CASCADE, organization_id uuid NOT NULL, account_id uuid NOT NULL, conversation_id uuid NOT NULL, direction text NOT NULL, source text NOT NULL, history boolean NOT NULL, event_time timestamptz NOT NULL);
CREATE INDEX fact_messages_period ON fact_messages(account_id,event_time);
CREATE TABLE fact_session_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES wa_accounts, state text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE report_exports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, user_id uuid NOT NULL REFERENCES users, account_id uuid NOT NULL REFERENCES wa_accounts, format text NOT NULL CHECK(format IN ('csv','xlsx')), filters jsonb NOT NULL, state text NOT NULL DEFAULT 'QUEUED', storage_key text, error_code text, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours');
CREATE TABLE integration_instances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, kind text NOT NULL, enabled boolean NOT NULL DEFAULT false CHECK(enabled=false), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE knowledge_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES wa_accounts, title text NOT NULL, body text NOT NULL, search tsvector GENERATED ALWAYS AS (to_tsvector('simple',title||' '||body)) STORED, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX knowledge_fts ON knowledge_documents USING gin(search);
